+    fn styled_pane_rows(&self, pane: PaneFocus, rows: &[(String, Style)]) -> Vec<Spans<'static>> {
+        rows.iter()
+            .enumerate()
+            .map(|(row, (line, style))| self.styled_pane_line(pane, row, line, *style))
+            .collect()
+    }
+
+    fn styled_pane_line(
+        &self,
+        pane: PaneFocus,
+        row: usize,
+        line: &str,
+        base_style: Style,
+    ) -> Spans<'static> {
+        let Some((start, end)) = self.selection_range_for_line(pane, row, line) else {
+            return Spans::from(vec![Span::styled(line.to_string(), base_style)]);
+        };
+        let chars = line.chars().collect::<Vec<_>>();
+        let start = start.min(chars.len());
+        let end = end.min(chars.len()).max(start);
+        let mut selected_style = base_style;
+        selected_style = selected_style.add_modifier(Modifier::REVERSED);
+        Spans::from(vec![
+            Span::styled(chars[..start].iter().collect::<String>(), base_style),
+            Span::styled(chars[start..end].iter().collect::<String>(), selected_style),
+            Span::styled(chars[end..].iter().collect::<String>(), base_style),
+        ])
+    }
+
+    fn selection_range_for_line(
+        &self,
+        pane: PaneFocus,
+        row: usize,
+        line: &str,
+    ) -> Option<(usize, usize)> {
+        let selection = self.visual_selection.as_ref()?;
+        if selection.pane != pane {
+            return None;
+        }
+        selection_range(selection, row, line.chars().count())
+    }
+
+    fn visual_cursor_screen_position(&self) -> Option<(u16, u16)> {
+        let selection = self.visual_selection.as_ref()?;
+        let layout = self.layout();
+        if selection.pane == PaneFocus::Left && !self.left_visible {
+            return None;
+        }
+        let pane_left = match selection.pane {
+            PaneFocus::Left => 0,
+            PaneFocus::Right => layout.left_width,
+        };
+        Some((
+            (selection.cursor.row + 2).min(usize::from(u16::MAX)) as u16,
+            pane_left
+                .saturating_add(2)
+                .saturating_add(selection.cursor.column.min(usize::from(u16::MAX)) as u16),
+        ))
+    }
