+
+fn content_lines(content: &str) -> Vec<String> {
+    let lines = content.lines().map(str::to_string).collect::<Vec<_>>();
+    if lines.is_empty() {
+        vec![String::new()]
+    } else {
+        lines
+    }
+}
+
+fn selected_row_range(selection: &VisualSelection) -> (usize, usize) {
+    if selection.anchor.row <= selection.cursor.row {
+        (selection.anchor.row, selection.cursor.row)
+    } else {
+        (selection.cursor.row, selection.anchor.row)
+    }
+}
+
+fn selection_range(
+    selection: &VisualSelection,
+    row: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    match selection.kind {
+        VisualSelectionKind::Line => {
+            let (start_row, end_row) = selected_row_range(selection);
+            (start_row..=end_row)
+                .contains(&row)
+                .then_some((0, line_len))
+        }
+        VisualSelectionKind::Block => {
+            let (start_row, end_row) = selected_row_range(selection);
+            if !(start_row..=end_row).contains(&row) {
+                return None;
+            }
+            let start = selection.anchor.column.min(selection.cursor.column);
+            let end = selection
+                .anchor
+                .column
+                .max(selection.cursor.column)
+                .saturating_add(1);
+            if line_len == 0 {
+                return Some((0, 0));
+            }
+            (start < line_len).then_some((start.min(line_len), end.min(line_len)))
+        }
+        VisualSelectionKind::Character => character_selection_range(selection, row, line_len),
+    }
+}
+
+fn character_selection_range(
+    selection: &VisualSelection,
+    row: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    let (start, end) = ordered_positions(selection.anchor, selection.cursor);
+    if row < start.row || row > end.row {
+        return None;
+    }
+    if line_len == 0 {
+        return Some((0, 0));
+    }
+
+    let range = if start.row == end.row {
+        (
+            start.column.min(line_len),
+            end.column.saturating_add(1).min(line_len),
+        )
+    } else if row == start.row {
+        (start.column.min(line_len), line_len)
+    } else if row == end.row {
+        (0, end.column.saturating_add(1).min(line_len))
+    } else {
+        (0, line_len)
+    };
+    Some(range)
+}
+
+fn ordered_positions(left: TextPosition, right: TextPosition) -> (TextPosition, TextPosition) {
+    if (left.row, left.column) <= (right.row, right.column) {
+        (left, right)
+    } else {
+        (right, left)
+    }
+}
+
+fn clamp_text_position(lines: &[String], mut position: TextPosition) -> TextPosition {
+    if lines.is_empty() {
+        return TextPosition { row: 0, column: 0 };
+    }
+    position.row = position.row.min(lines.len() - 1);
+    let max_column = lines[position.row].chars().count().saturating_sub(1);
+    position.column = position.column.min(max_column);
+    position
+}
+
+fn line_char_range(line: &str, start: usize, end: usize) -> String {
+    line.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
+
+fn osc52_copy_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::with_capacity(bytes.len().saturating_add(2) / 3 * 4);
+    let mut index = 0;
+    while index < bytes.len() {
+        let first = bytes[index];
+        let second = bytes.get(index + 1).copied().unwrap_or(0);
+        let third = bytes.get(index + 2).copied().unwrap_or(0);
+
+        encoded.push(TABLE[(first >> 2) as usize] as char);
+        encoded.push(TABLE[(((first & 0b0000_0011) << 4) | (second >> 4)) as usize] as char);
+        if index + 1 < bytes.len() {
+            encoded.push(TABLE[(((second & 0b0000_1111) << 2) | (third >> 6)) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+        if index + 2 < bytes.len() {
+            encoded.push(TABLE[(third & 0b0011_1111) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+
+        index += 3;
+    }
+    encoded
