};

fn main() {
    let root = std::env::current_dir().expect("current dir");
    let backend = CodexBackend::new(
        CodexCommandConfig::new(root.clone()),
        PromptPolicy::for_project(&root).expect("project prompt policy"),
    );
    let chat = CommandChat::new(root, backend);
    let mut controller = WorkLeafController::new(chat);

    let agent_id = controller.create_agent("").expect("create real agent");
    if !controller.wait_for_idle(Duration::from_secs(180)) {
        eprintln!("real agent launch timed out");
        std::process::exit(2);
    }

    controller
        .send_message(&agent_id, "/status")
        .expect("send /status");
    if !controller.wait_for_idle(Duration::from_secs(120)) {
        eprintln!("real /status command timed out");
        std::process::exit(3);
    }
    let status_snapshot = controller.snapshot();
    let status_session = status_snapshot
        .session(&agent_id)
        .expect("status session exists");
    println!(
        "STATUS_USER_LINE={}",
        status_session.lines.iter().any(|line| line == "user: /status")
    );
    println!("STATUS_TRANSCRIPT_START");
    for line in &status_session.lines {
        println!("{line}");
    }
    println!("STATUS_TRANSCRIPT_END");

    controller
        .send_message(&agent_id, "/fork")
        .expect("send /fork");
    if !controller.wait_for_idle(Duration::from_secs(120)) {
        eprintln!("real /fork command timed out");
        std::process::exit(4);
